package br.com.gustavo.nossotempo;
import android.app.Activity;import android.graphics.Color;import android.os.Bundle;import android.view.Gravity;import android.widget.*;
public class CelebrationActivity extends Activity{@Override protected void onCreate(Bundle b){super.onCreate(b);setShowWhenLocked(true);setTurnScreenOn(true);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setPadding(40,40,40,40);r.setBackgroundColor(Color.rgb(48,10,38));TextView title=t("♥\nHOJE É O DIA DE VOCÊS!",34,Color.WHITE);title.setTypeface(null,1);RelationshipTime.Parts p=RelationshipTime.now();String mark=p.years>0&&p.months==0&&p.days==0?p.years+(p.years==1?" ano juntos":" anos juntos"):(p.years*12+p.months)+" meses juntos";Button close=new Button(this);close.setText("FECHAR");close.setOnClickListener(v->finish());r.addView(title);r.addView(t(mark+"\n\nDesde 12 de setembro de 2026, às 16:43",20,Color.rgb(255,205,222)));r.addView(close);setContentView(r);}private TextView t(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.CENTER);v.setPadding(0,18,0,18);return v;}}
